using Godot;
using Settings=Godot.Collections.Dictionary;
public partial class ActorFontPickerOperations:RefCounted
{
    private readonly ActorTextSettingsOperations _text=new();
    public StyleBoxFlat box(Color color,Color border,int radius,int width){var style=new StyleBoxFlat{BgColor=color,BorderColor=border,ContentMarginLeft=10,ContentMarginRight=10};style.SetBorderWidthAll(width);style.SetCornerRadiusAll(radius);return style;}
    public void setup(PopupPanel owner,string selected)
    {
        owner.Set("current_family",selected);owner.Set("families",_text.system_fonts());owner.AddThemeStyleboxOverride("panel",box(new Color("101923"),new Color("496579"),12,2));var margin=new MarginContainer();foreach(string side in new[]{"left","right","top","bottom"})margin.AddThemeConstantOverride("margin_"+side,16);owner.AddChild(margin);var column=new VBoxContainer();column.AddThemeConstantOverride("separation",10);margin.AddChild(column);var header=new HBoxContainer();column.AddChild(header);var titles=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};header.AddChild(titles);var title=new Label{Text="Choose a font"};title.AddThemeFontSizeOverride("font_size",21);title.AddThemeColorOverride("font_color",new Color("eff7ff"));titles.AddChild(title);var count=new Label();owner.Set("result_count",count);count.AddThemeFontSizeOverride("font_size",11);count.AddThemeColorOverride("font_color",new Color("7f9eb3"));titles.AddChild(count);var close=new Button{Text="×",CustomMinimumSize=new Vector2(38,34)};close.Pressed+=owner.Hide;header.AddChild(close);var search=new LineEdit{Name="FontSearch",PlaceholderText="Search installed fonts…",ClearButtonEnabled=true,CustomMinimumSize=new Vector2(0,40)};owner.Set("search",search);search.TextChanged+=query=>rebuild(owner,query);column.AddChild(search);var preview=new CheckButton{Text="Preview using text content",Disabled=owner.Get("preview_text").AsString().Length==0};column.AddChild(preview);preview.Toggled+=enabled=>{owner.Set("preview_actual",enabled);rebuild(owner,search.Text);};var scroll=new ScrollContainer{CustomMinimumSize=new Vector2(430,350),HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled};column.AddChild(scroll);var options=new VBoxContainer{Name="FontOptions",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};options.AddThemeConstantOverride("separation",4);owner.Set("options",options);scroll.AddChild(options);rebuild(owner,"");
    }
    public void rebuild(PopupPanel owner,string query)
    {
        var options=owner.Get("options").As<VBoxContainer>();foreach(var child in options.GetChildren()){options.RemoveChild(child);child.QueueFree();}query=query.Trim().ToLowerInvariant();int count=0;string selected=owner.Get("current_family").AsString();foreach(string family in owner.Get("families").AsStringArray()){if(query.Length>0&&!family.ToLowerInvariant().Contains(query))continue;count++;var row=new Button{Name="FontOption",Text=(family==selected?"✓  ":"    ")+(owner.Get("preview_actual").AsBool()?owner.Get("preview_text").AsString():family),TooltipText=family,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,Alignment=HorizontalAlignment.Left,CustomMinimumSize=new Vector2(0,42)};row.AddThemeFontOverride("font",_text.font(new Settings{[new StringName("font")]=family}));row.AddThemeFontSizeOverride("font_size",16);row.AddThemeColorOverride("font_color",new Color(family!=selected?"eef5fa":"78e1c6"));row.AddThemeStyleboxOverride("normal",box(new Color("17232f"),new Color("243746"),6,1));row.AddThemeStyleboxOverride("hover",box(new Color("294153"),new Color("65d8bd"),6,1));row.Pressed+=()=>choose(owner,family);options.AddChild(row);}owner.Get("result_count").As<Label>().Text=count+" installed font"+(count==1?"":"s");if(count==0){var empty=new Label{Text="No installed fonts match that search."};empty.AddThemeColorOverride("font_color",new Color("95aabd"));options.AddChild(empty);}
    }
    public void choose(PopupPanel owner,string family){owner.EmitSignal("font_chosen",family);owner.Hide();}
    public void build_dimension(AcceptDialog owner,string asset)
    {
        owner.Title="Add to scene";owner.GetOkButton().Hide();owner.Canceled+=()=>owner.EmitSignal("choice_made",new StringName(""));var column=new VBoxContainer();column.AddThemeConstantOverride("separation",14);owner.AddChild(column);var heading=new Label{Text=asset,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis};heading.AddThemeFontSizeOverride("font_size",18);column.AddChild(heading);var row=new HBoxContainer();row.AddThemeConstantOverride("separation",12);column.AddChild(row);foreach(string dimension in new[]{"2d","3d"}){var button=new Button{Name="Choose"+dimension.ToUpperInvariant(),Text=dimension=="2d"?"▣  2D UI\nScreen-space overlay":"◇  3D Scene\nPosition in the world",CustomMinimumSize=new Vector2(190,90),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};var style=new StyleBoxFlat{BgColor=new Color("243742"),BorderColor=new Color(dimension=="2d"?"85d9c0":"bfa4ed")};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(8);button.AddThemeStyleboxOverride("normal",style);var hover=(StyleBoxFlat)style.Duplicate();hover.BgColor=new Color("36525a");button.AddThemeStyleboxOverride("hover",hover);row.AddChild(button);button.Pressed+=()=>{owner.Hide();owner.EmitSignal("choice_made",new StringName(dimension));};}
    }
}
